[meta]
name = Herran's Castle
ambient = 0.86 0.8 0.74
fog = 0.66 0.67 0.76
fog_range = 22 120
model_range = 64
indoor_range = 26
sky = storm
torch = 6 0.95 0.8 0.6
start = 27 81 -90
default = _
entity_floor = auto
roofs = true
edge_top = -40
edge_tex = herran_ashlar

// Herran's Castle, high over a sea of cloud between the sun and Vesperholm's moon: the seat of Herran,
// a son of Lyra the Embracer, who kept the fifth seal, the Auric Sigil, the one the king never held.
// His sister Ilvane bent hers to the moon; he bent his to his own flesh. He wanted his mother's many
// hands, and grafted arms onto his drakes, and then onto himself. You come up the stair of light from
// Lyra's altar in Vesperholm onto the Cloud Quay, where the shrine stands; through the gatehouse into
// the Lower Court, the Open Laboratory west of it and the Glasshouse Aviary east; up the Great Stair
// to the Belvedere Terrace; through the Clock Tower and over the High Bridge to the Belvedere, and the
// North Bridge on to the Spire Plaza and the foot of Herran's Spire, whose door the Spire Key opens.
// Hidden laboratories lie behind false walls: north of the open lab, south of the aviary, and behind
// the clock tower's top room. The lift in the Belvedere drops to the court: the short way home.

[legend]
// The sea of cloud far below: a sheer fall that no one lives through.
_ = floor tex=cloud_sea h=-40 side=herran_ashlar chasm fall=cloud void
// The castle's walls in red and cream brick, its towers, the spire, and the balustrades and parapets.
# = wall tex=herran_brick top=9 cap=herran_slate
% = wall tex=herran_brick top=16 cap=herran_slate
& = wall tex=herran_brick top=24 cap=herran_slate
b = wall tex=herran_ashlar top=1.1 cap=herran_ashlar
u = wall tex=herran_ashlar top=7.1 cap=herran_ashlar
v = wall tex=herran_ashlar top=11.1 cap=herran_ashlar
// The Cloud Quay, and the gatehouse's passage half a metre up.
, = floor tex=herran_ashlar h=0 side=herran_ashlar
p = floor tex=encaustic_tile h=0.5 ceil=5 ceil_tex=herran_ashlar side=herran_brick roof=9
// The Lower Court, and the aviary under the open sky.
. = floor tex=herran_ashlar h=1 side=herran_ashlar
a = floor tex=herran_ashlar h=1 side=herran_brick
// The laboratories: the open one, and the hidden ones.
l = floor tex=lab_tile h=1 ceil=4.5 ceil_tex=lab_tile side=lab_tile roof=9 dark=0.25
s = floor tex=lab_tile h=1 ceil=4 ceil_tex=lab_tile side=lab_tile roof=9 dark=0.45
k = floor tex=lab_tile h=10 ceil=13.5 ceil_tex=lab_tile side=lab_tile roof=16 dark=0.45
// The Great Stair, half a metre a tile from the court up to the terrace.
1 = floor tex=herran_ashlar h=1.5 side=herran_ashlar
2 = floor tex=herran_ashlar h=2 side=herran_ashlar
3 = floor tex=herran_ashlar h=2.5 side=herran_ashlar
4 = floor tex=herran_ashlar h=3 side=herran_ashlar
5 = floor tex=herran_ashlar h=3.5 side=herran_ashlar
6 = floor tex=herran_ashlar h=4 side=herran_ashlar
7 = floor tex=herran_ashlar h=4.5 side=herran_ashlar
8 = floor tex=herran_ashlar h=5 side=herran_ashlar
9 = floor tex=herran_ashlar h=5.5 side=herran_ashlar
// The Belvedere Terrace, 6 m up.
t = floor tex=herran_ashlar h=6 side=herran_ashlar
// The Clock Tower's hall, the stair up inside its wall, and the top rooms of both towers at 10 m.
i = floor tex=encaustic_tile h=6 ceil=10.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.2
α = floor tex=encaustic_tile h=6.5 ceil=11 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
β = floor tex=encaustic_tile h=7 ceil=11.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
γ = floor tex=encaustic_tile h=7.5 ceil=12 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
δ = floor tex=encaustic_tile h=8 ceil=12.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
ε = floor tex=encaustic_tile h=8.5 ceil=13 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
ζ = floor tex=encaustic_tile h=9 ceil=13.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
η = floor tex=encaustic_tile h=9.5 ceil=14 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
j = floor tex=encaustic_tile h=10 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.2
// The Belvedere's long gallery down to the lift, and the lift's shaft, down to the court.
m = floor tex=encaustic_tile h=10 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=16 dark=0.3
e = floor tex=iron_grating h=1 ceil=14.5 ceil_tex=herran_ashlar side=herran_brick roof=16 chasm
// The skybridges' iron decks, and the Spire Plaza, 10 m up.
h = floor tex=iron_grating h=10 side=herran_ashlar
n = floor tex=herran_ashlar h=10 side=herran_ashlar
// The passage into the foot of the Spire.
q = floor tex=encaustic_tile h=10 ceil=15 ceil_tex=herran_ashlar side=herran_brick roof=24 dark=0.3

