[entities]
// The stair of light down to Lyra's altar in Vesperholm, at the quay's south edge, and the shrine.
A = exit map=vesperholm at=34,18,180 label=Descend_to_Vesperholm model=sky_stair way=out yaw=90
B = save_statue
// The Open Laboratory's door off the court, and the false walls of the hidden ones.
C = door
W = secret_wall
// The Belvedere's lift down to the court's north-east corner: fastened until its first ride down.
L = lift top=10 start=top locked model=cage on=e
// Finds: the Spire Key in the open lab, and what the hidden labs and the aviary keep.
K = chest item=spire_key gold=120 model=banded
D = chest item=graft_draught count=2 gold=140 model=coffer
E = chest item=herran_bonesaw gold=150 model=banded
F = chest item=sun_tincture count=2 gold=160 model=coffer
G = chest item=bitter_root count=2 gold=110
// The door at the foot of Herran's Spire, and the way in at the passage's end.
H = door key=spire_key
J = exit map=herran_spire at=12,37,-90 label=Climb_the_Spire model=spire_door yaw=90 boss=herran_dead
// Gaslight on the quay, in the court, on the terrace and the plaza, and the drake fountain, dry.
M = gas_lamp
N = drake_fountain
// The laboratories' dressing: specimen jars, alembic benches, vats, the operating table and shelves.
O = specimen_jar
P = alembic_bench
Q = vat
R = surgery_table
S = potion_shelf
// The skyline: the gatehouse's twin towers, the clock tower, the Belvedere's loggia, the Spire's
// needle, the round tower over the hidden lab and one over the hall; the aviary's glasshouse vault.
T = herran_tower style=octagon height=12 on=%
U = herran_tower style=clock height=16 on=%
V = herran_tower style=belvedere height=12 on=%
X = herran_tower style=needle height=34 on=&
Y = herran_tower style=round height=14 on=%
Z = herran_tower style=round height=9 on=#
I = glasshouse span=18,38 height=8 on=a
// Herran's creatures: Drake Magi in their gowns, Grafted Drakes on the wing, Vat Spawn in the labs.
Ä = drake_magus
Å = grafted_drake
Æ = vat_spawn
// Herran's ledger in the open lab, and his journal, a page in each hidden one.
À = hint text="A ledger of drakes, each with arms sewn on.|The last entries are in a shakier hand."
Á = hint text="Mother holds out six hands. I have two.|The drakes take the grafts well. Next, mine."
Â = hint text="Ilvane wed the moon on her seal to keep her city.|I shall wed the sun's to my own flesh."
Ã = hint text="My sister and I were born of the Embracer.|Neither she nor Mother answers me now."
